import React, { useState, useEffect, useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import { OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

const transitionDuration = 2; // Duration for each transition
const displayDuration = 6; // Duration each model is displayed before transitioning

const ModelLoader = ({ modelPath, nextModelPath, morphProgress }) => {
  const [currentGeometry, setCurrentGeometry] = useState(null);
  const [nextGeometry, setNextGeometry] = useState(null);

  useEffect(() => {
    if (modelPath) {
      const loader = new OBJLoader();
      loader.load(modelPath, (obj) => {
        setCurrentGeometry(extractGeometryFromObject(obj));
      });
    }
    if (nextModelPath) {
      const loader = new OBJLoader();
      loader.load(nextModelPath, (obj) => {
        setNextGeometry(extractGeometryFromObject(obj));
      });
    }
  }, [modelPath, nextModelPath]);

  const morphGeometry =
    currentGeometry && nextGeometry
      ? morphGeometries(currentGeometry, nextGeometry, morphProgress)
      : currentGeometry;

  return (
    <group>
      {morphGeometry && (
        <mesh>
          <bufferGeometry attach="geometry" {...morphGeometry} />
          <meshStandardMaterial color="#ff6347" />
        </mesh>
      )}
    </group>
  );
};

function extractGeometryFromObject(obj) {
  let mergedGeometry = new THREE.BufferGeometry();
  obj.traverse((child) => {
    if (child.isMesh) {
      mergedGeometry = child.geometry.clone(); // Return first mesh found
    }
  });
  return mergedGeometry;
}

function morphGeometries(geometry1, geometry2, t) {
  const morphGeometry = geometry1.clone();
  const position1 = geometry1.attributes.position.array;
  const position2 = geometry2.attributes.position.array;
  const morphPosition = morphGeometry.attributes.position.array;

  for (let i = 0; i < morphPosition.length; i++) {
    morphPosition[i] = position1[i] + (position2[i] - position1[i]) * t;
  }
  morphGeometry.attributes.position.needsUpdate = true;
  return morphGeometry;
}

const App = () => {
  const [models, setModels] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [fileIndex, setFileIndex] = useState(0); // To track files within an array
  const [morphProgress, setMorphProgress] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(false);

  useEffect(() => {
    fetch('./models.json')
      .then((response) => response.json())
      .then((data) => setModels(data))
      .catch((error) => console.error('Error loading models:', error));
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setIsTransitioning(true); // Start transition
    }, displayDuration * 1000);

    return () => clearInterval(interval);
  }, []);

  useFrame((_, delta) => {
    if (isTransitioning) {
      setMorphProgress((prev) => Math.min(prev + delta / transitionDuration, 1));

      if (morphProgress >= 1) {
        setIsTransitioning(false);
        setMorphProgress(0);

        // Move to the next file if it's an array, or to the next model
        const currentModel = models[currentIndex];
        const files = Array.isArray(currentModel.file) ? currentModel.file : [currentModel.file];

        if (fileIndex < files.length - 1) {
          setFileIndex((prev) => prev + 1);
        } else {
          setFileIndex(0);
          setCurrentIndex((prevIndex) => (prevIndex + 1) % models.length);
        }
      }
    }
  });

  if (models.length === 0) {
    return <div>Loading models...</div>;
  }

  // Get current and next model file paths
  const currentModel = models[currentIndex];
  const files = Array.isArray(currentModel.file) ? currentModel.file : [currentModel.file];
  const currentFile = files[fileIndex];
  const nextFile = files[(fileIndex + 1) % files.length];

  return (
    <div style={{ display: 'flex' }}>
      <div style={{ flex: 1, height: '100vh' }}>
        <Canvas
          style={{ backgroundColor: 'black' }}
          camera={{
            position: [2.5, 2.5, 2.5],
            fov: 45,
          }}
        >
          <ambientLight intensity={0.5} />
          <spotLight position={[10, 10, 10]} intensity={1} />
          <directionalLight position={[5, 5, 5]} intensity={1} />
          <ModelLoader
            modelPath={`./stls/${currentFile}`}
            nextModelPath={`./stls/${nextFile}`}
            morphProgress={morphProgress}
          />
          <OrbitControls
            enableZoom={false}
            minPolarAngle={Math.PI / 4}
            maxPolarAngle={Math.PI / 4}
            minAzimuthAngle={-Math.PI / 4}
            maxAzimuthAngle={Math.PI / 4}
          />
        </Canvas>
      </div>
    </div>
  );
};

export default App;
